using System.ComponentModel;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;

namespace JPSoftworks.Regedit.Controls.Lists;

/// <summary>
///     Item template root generated by <see cref="ColumnListView" />. Cells are created lazily the first time their
///     column is shown and are reused across recycling; width-only changes touch just the column definitions.
/// </summary>
public sealed partial class ColumnRow : Grid
{
    private readonly Dictionary<ListColumn, FrameworkElement> _cells = [];
    private ColumnArrangement _applied = ColumnArrangement.Empty;
    private ColumnListView? _owner;
    private (ListColumn Column, TextBox Box)? _editor;
    private INotifyPropertyChanged? _observedItem;

    public ColumnRow()
    {
        this.Background = new SolidColorBrush(Microsoft.UI.Colors.Transparent);
        this.Loaded += this.RowLoaded;
        this.Unloaded += this.RowUnloaded;
        this.DataContextChanged += (_, _) =>
        {
            this.ObserveItem();
            this.UpdateAutomationName();
        };
    }

    private void ObserveItem()
    {
        if (this._observedItem is not null)
        {
            this._observedItem.PropertyChanged -= this.ItemPropertyChanged;
        }

        this._observedItem = this.IsLoaded ? this.DataContext as INotifyPropertyChanged : null;
        if (this._observedItem is not null)
        {
            this._observedItem.PropertyChanged += this.ItemPropertyChanged;
        }
    }

    private void ItemPropertyChanged(object? sender, PropertyChangedEventArgs args)
    {
        this.UpdateAutomationName();
    }

    internal IEnumerable<(ListColumn Column, FrameworkElement Cell)> Cells =>
        this._cells.Select(pair => (pair.Key, pair.Value));

    internal void SetOwner(ColumnListView owner)
    {
        this._owner = owner;
        this.UpdateAutomationName();
    }

    // The list item's accessible name comes from its template root.
    internal void UpdateAutomationName()
    {
        if (this._owner?.ItemAutomationName is { } name)
        {
            Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(this, name(this.DataContext) ?? string.Empty);
        }
    }

    internal FrameworkElement? CellFor(ListColumn column)
    {
        return this._cells.GetValueOrDefault(column);
    }

    /// <summary>The visible column under <paramref name="x" /> in row coordinates, or null over spacing and padding.</summary>
    internal ListColumn? ColumnAt(double x)
    {
        var left = this.Padding.Left;
        for (var slot = 0; slot < this._applied.Slots.Count; slot++)
        {
            var width = this._applied.Widths[slot];
            if (x >= left && x < left + width)
            {
                return this._applied.Slots[slot];
            }

            left += width + this._applied.Spacing;
        }

        return null;
    }

    internal TextBox ShowEditor(ListColumn column, string text)
    {
        this.HideEditor();
        var box = new TextBox
        {
            Text = text,
            MinHeight = 0,
            MinWidth = 0,
            Padding = new Thickness(6, 2, 6, 2),
            Margin = new Thickness(-6, -2, 0, -2),
            VerticalAlignment = VerticalAlignment.Center,
            IsSpellCheckEnabled = false
        };
        Microsoft.UI.Xaml.Automation.AutomationProperties.SetAutomationId(box, "InlineEditor");
        Microsoft.UI.Xaml.Automation.AutomationProperties.SetName(box, "Rename " + column.Name);
        Canvas.SetZIndex(box, 1);
        SetColumn(box, Math.Max(0, this._applied.SlotOf(column)));
        if (this.CellFor(column) is { } cell)
        {
            cell.Opacity = 0;
        }

        this.Children.Add(box);
        this._editor = (column, box);
        return box;
    }

    internal void HideEditor()
    {
        if (this._editor is not { } editor)
        {
            return;
        }

        this._editor = null;
        this.Children.Remove(editor.Box);
        if (this.CellFor(editor.Column) is { } cell)
        {
            cell.Opacity = 1;
        }
    }

    internal void RefreshText()
    {
        foreach (var (column, cell) in this._cells)
        {
            column.RefreshCell(cell, this.DataContext);
        }
    }

    internal void Apply(ColumnArrangement arrangement)
    {
        if (ReferenceEquals(arrangement, this._applied))
        {
            return;
        }

        if (arrangement.ColumnsVersion != this._applied.ColumnsVersion)
        {
            foreach (var stale in this._cells.Keys.Where(column => !arrangement.Declared.Contains(column)).ToArray())
            {
                this.Children.Remove(this._cells[stale]);
                this._cells.Remove(stale);
            }
        }

        this.ColumnSpacing = arrangement.Spacing;
        SetWidths(this, arrangement.Widths);
        foreach (var (column, cell) in this._cells)
        {
            if (arrangement.SlotOf(column) < 0)
            {
                cell.Visibility = Visibility.Collapsed;
            }
        }

        for (var slot = 0; slot < arrangement.Slots.Count; slot++)
        {
            var column = arrangement.Slots[slot];
            if (!this._cells.TryGetValue(column, out var cell))
            {
                cell = column.CreateCell();
                this._cells.Add(column, cell);
                this.Children.Add(cell);
            }

            SetColumn(cell, slot);
            cell.Visibility = Visibility.Visible;
        }

        if (this._editor is { } editor && arrangement.SlotOf(editor.Column) is var editorSlot and >= 0)
        {
            SetColumn(editor.Box, editorSlot);
        }

        this._applied = arrangement;
    }

    internal static void SetWidths(Grid grid, IReadOnlyList<double> widths)
    {
        while (grid.ColumnDefinitions.Count > widths.Count)
        {
            grid.ColumnDefinitions.RemoveAt(grid.ColumnDefinitions.Count - 1);
        }

        for (var index = 0; index < widths.Count; index++)
        {
            var width = new GridLength(widths[index]);
            if (index < grid.ColumnDefinitions.Count)
            {
                if (grid.ColumnDefinitions[index].Width != width)
                {
                    grid.ColumnDefinitions[index].Width = width;
                }
            }
            else
            {
                grid.ColumnDefinitions.Add(new ColumnDefinition { Width = width });
            }
        }
    }

    private void RowLoaded(object sender, RoutedEventArgs args)
    {
        this.ObserveItem();
        for (DependencyObject? parent = VisualTreeHelper.GetParent(this);
             parent is not null;
             parent = VisualTreeHelper.GetParent(parent))
        {
            if (parent is ColumnListView owner)
            {
                this._owner = owner;
                owner.Register(this);
                return;
            }
        }
    }

    private void RowUnloaded(object sender, RoutedEventArgs args)
    {
        if (this._observedItem is not null)
        {
            this._observedItem.PropertyChanged -= this.ItemPropertyChanged;
            this._observedItem = null;
        }

        this._owner?.Unregister(this);
        this._owner = null;
    }
}
